:root {
  --color-bg: #2b2b3c;
  --color-card: #f4f4f8;
  --color-primary: #6c5ce7;
  --color-accent: #00cec9;
  --color-text: #2d3436;
  --color-text-light: #636e72;
  --pixel-size: 4px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--color-bg);
  background-image: linear-gradient(45deg, #35354a 25%, transparent 25%),
    linear-gradient(-45deg, #35354a 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #35354a 75%),
    linear-gradient(-45deg, transparent 75%, #35354a 75%);
  background-size: 20px 20px;
  background-position: 0 0, 0 10px, 10px -10px, -10px 0px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  color: var(--color-text);
}

.card {
  background: var(--color-card);
  width: 100%;
  max-width: 600px;
  padding: 32px;
  border: var(--pixel-size) solid var(--color-primary);
  box-shadow: 8px 8px 0 var(--color-primary), 16px 16px 0 rgba(0, 0, 0, 0.2);
  image-rendering: pixelated;
}

h1 {
  font-size: 24px;
  margin-bottom: 24px;
  text-align: center;
  color: var(--color-primary);
  letter-spacing: 2px;
  text-transform: uppercase;
}

.tabs {
  display: flex;
  gap: 4px;
  margin-bottom: 16px;
  flex-wrap: wrap;
}

[role="tab"] {
  flex: 1 1 auto;
  min-width: 80px;
  padding: 12px 16px;
  font-size: 16px;
  font-weight: 600;
  background: #e0e0e8;
  border: 3px solid transparent;
  color: var(--color-text-light);
  cursor: pointer;
  transition: background 0.1s, color 0.1s, border-color 0.1s;
  font-family: inherit;
}

[role="tab"]:hover {
  background: #d0d0e0;
  color: var(--color-text);
}

[role="tab"]:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

[role="tab"][aria-selected="true"] {
  background: var(--color-primary);
  color: #fff;
  border-color: var(--color-accent);
}

[role="tab"]:active {
  transform: translateY(2px);
}

textarea {
  width: 100%;
  padding: 12px;
  font-family: inherit;
  font-size: 16px;
  line-height: 1.5;
  border: 3px solid #b0b0c0;
  background: #fff;
  resize: vertical;
  min-height: 150px;
  color: var(--color-text);
}

textarea:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px var(--color-accent);
}

.count {
  margin-top: 8px;
  font-size: 14px;
  color: var(--color-text-light);
  text-align: right;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

[hidden] {
  display: none !important;
}

@media (max-width: 400px) {
  body {
    padding: 12px;
  }
  .card {
    padding: 16px;
    box-shadow: 4px 4px 0 var(--color-primary), 8px 8px 0 rgba(0, 0, 0, 0.2);
  }
  h1 {
    font-size: 20px;
  }
  [role="tab"] {
    padding: 10px 8px;
    font-size: 14px;
    min-width: 60px;
  }
}

(function () {
  'use strict';

  var tabs = Array.prototype.slice.call(document.querySelectorAll('[role="tab"]'));
  var panels = Array.prototype.slice.call(document.querySelectorAll('[role="tabpanel"]'));

  function getTabIndex(tab) {
    return tabs.indexOf(tab);
  }

  function activateTab(tab) {
    tabs.forEach(function (t) {
      var selected = t === tab;
      t.setAttribute('aria-selected', selected ? 'true' : 'false');
      t.setAttribute('tabindex', selected ? '0' : '-1');
    });
    panels.forEach(function (p) {
      p.hidden = p.id !== 'panel-' + tab.id.replace('tab-', '');
    });
    var textarea = document.getElementById('notes-' + tab.id.replace('tab-', ''));
    if (textarea) textarea.focus();
  }

  function updateCount(textarea) {
    var id = textarea.id.replace('notes-', 'count-');
    var countEl = document.getElementById(id);
    if (countEl) {
      var len = textarea.value.length;
      countEl.textContent = len + ' character' + (len === 1 ? '' : 's');
    }
  }

  tabs.forEach(function (tab) {
    tab.addEventListener('click', function () {
      activateTab(tab);
    });

    tab.addEventListener('keydown', function (e) {
      var idx = getTabIndex(tab);
      var newIdx = null;
      if (e.key === 'ArrowRight') {
        newIdx = (idx + 1) % tabs.length;
      } else if (e.key === 'ArrowLeft') {
        newIdx = (idx - 1 + tabs.length) % tabs.length;
      } else if (e.key === 'Home') {
        newIdx = 0;
      } else if (e.key === 'End') {
        newIdx = tabs.length - 1;
      }
      if (newIdx !== null) {
        e.preventDefault();
        tabs[newIdx].focus();
        activateTab(tabs[newIdx]);
      }
    });
  });

  panels.forEach(function (panel) {
    var textarea = panel.querySelector('textarea');
    if (textarea) {
      textarea.addEventListener('input', function () {
        updateCount(textarea);
      });
      updateCount(textarea);
    }
  });
})();
